-- Canonical first-version schema generated from BACKEND_API_REQUIREMENTS.md.
CREATE DATABASE IF NOT EXISTS askustours CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE askustours;
SET default_storage_engine=InnoDB;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','operator','reviewer') NOT NULL DEFAULT 'admin',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id CHAR(36) PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(190),phone VARCHAR(40),role ENUM('customer','partner') NOT NULL DEFAULT 'customer',partner_intent BOOLEAN NOT NULL DEFAULT FALSE,verified_at DATETIME NULL,avatar VARCHAR(40),photo_upload_id CHAR(36),profile_json JSON NOT NULL,preferences_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(email),UNIQUE(phone));
CREATE TABLE auth_challenges (id CHAR(36) PRIMARY KEY,channel ENUM('email','phone') NOT NULL,destination VARCHAR(190) NOT NULL,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,attempts SMALLINT UNSIGNED NOT NULL DEFAULT 0,consumed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(destination));
CREATE TABLE sessions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,access_token_hash CHAR(64) NOT NULL UNIQUE,refresh_token_hash CHAR(64) NOT NULL UNIQUE,access_expires_at DATETIME NOT NULL,refresh_expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE uploads (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,purpose VARCHAR(40) NOT NULL,file_name VARCHAR(190) NOT NULL,content_type VARCHAR(80) NOT NULL,path VARCHAR(255) NOT NULL,size_bytes INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE content_documents (slug VARCHAR(100) PRIMARY KEY,version VARCHAR(40) NOT NULL,title_json JSON NOT NULL,body_json JSON NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE home_config (id TINYINT UNSIGNED PRIMARY KEY DEFAULT 1,config_json JSON NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE driver_services (id CHAR(36) PRIMARY KEY,owner_user_id CHAR(36),status ENUM('draft','review','published','paused','rejected') NOT NULL DEFAULT 'draft',city VARCHAR(100) NOT NULL,category VARCHAR(80) NOT NULL,title_json JSON NOT NULL,service_json JSON NOT NULL,rating DECIMAL(3,2) NOT NULL DEFAULT 0,review_count INT UNSIGNED NOT NULL DEFAULT 0,revision INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,city));
CREATE TABLE guide_services (id CHAR(36) PRIMARY KEY,owner_user_id CHAR(36),status ENUM('draft','review','published','paused','rejected') NOT NULL DEFAULT 'draft',city VARCHAR(100) NOT NULL,title_json JSON NOT NULL,service_json JSON NOT NULL,rating DECIMAL(3,2) NOT NULL DEFAULT 0,review_count INT UNSIGNED NOT NULL DEFAULT 0,revision INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(owner_user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,city));
CREATE TABLE service_calendar (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,service_type ENUM('driver','guide') NOT NULL,service_id CHAR(36) NOT NULL,service_date DATE NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,price_minor INT UNSIGNED,details_json JSON NOT NULL,UNIQUE(service_type,service_id,service_date));
CREATE TABLE reviews (id CHAR(36) PRIMARY KEY,service_type ENUM('driver','guide') NOT NULL,service_id CHAR(36) NOT NULL,rating TINYINT UNSIGNED NOT NULL,author_name VARCHAR(120) NOT NULL,comment TEXT NOT NULL,verified BOOLEAN NOT NULL DEFAULT FALSE,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(service_type,service_id,rating));
CREATE TABLE travel_packages (id CHAR(36) PRIMARY KEY,status ENUM('draft','published','paused','archived') NOT NULL DEFAULT 'draft',revision INT UNSIGNED NOT NULL DEFAULT 1,package_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE quotes (id CHAR(36) PRIMARY KEY,user_id CHAR(36),service_type ENUM('driver','guide') NOT NULL,service_id CHAR(36) NOT NULL,request_json JSON NOT NULL,quote_json JSON NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'EUR',total_minor INT UNSIGNED NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE reservations (id CHAR(36) PRIMARY KEY,customer_user_id CHAR(36) NOT NULL,partner_user_id CHAR(36),quote_id CHAR(36) NOT NULL,service_type ENUM('driver','guide') NOT NULL,service_id CHAR(36) NOT NULL,status ENUM('requested','assigned','accepted','declined','cancelled','completed') NOT NULL DEFAULT 'requested',payment_status ENUM('notCollected','pending','paid','refunded') NOT NULL DEFAULT 'notCollected',snapshot_json JSON NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,idempotency_key VARCHAR(190) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(customer_user_id) REFERENCES users(id),FOREIGN KEY(partner_user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(quote_id) REFERENCES quotes(id),UNIQUE(customer_user_id,idempotency_key),INDEX(status));
CREATE TABLE favorites (user_id CHAR(36) NOT NULL,driver_service_id CHAR(36) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,driver_service_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(driver_service_id) REFERENCES driver_services(id) ON DELETE CASCADE);
CREATE TABLE basket_items (id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,item_type ENUM('driver','guide') NOT NULL,item_json JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE trip_drafts (draft_key VARCHAR(120) NOT NULL,user_id CHAR(36) NOT NULL,answers_json JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,draft_key),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE trip_requests (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,status ENUM('draft','submitted','in_review','proposal_ready','closed') NOT NULL DEFAULT 'draft',answers_json JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,privacy_version VARCHAR(40),submitted_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(status));
CREATE TABLE partner_profiles (user_id CHAR(36) PRIMARY KEY,status ENUM('draft','submitted','approved','rejected','suspended') NOT NULL DEFAULT 'draft',profile_json JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,submitted_at DATETIME,reviewed_at DATETIME,reviewed_by BIGINT UNSIGNED,review_notes TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES admins(id) ON DELETE SET NULL);
CREATE TABLE partner_service_drafts (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,service_type ENUM('driver','guide') NOT NULL,status ENUM('draft','review','approved','rejected') NOT NULL DEFAULT 'draft',service_json JSON NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE wallet_ledger (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,wallet_type ENUM('customer','partner') NOT NULL,entry_type VARCHAR(40) NOT NULL,amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'EUR',status ENUM('pending','available','paid','void') NOT NULL,reference_type VARCHAR(40),reference_id CHAR(36),description VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,wallet_type,status));
CREATE TABLE idempotency_keys (user_id CHAR(36) NOT NULL,operation VARCHAR(80) NOT NULL,key_value VARCHAR(190) NOT NULL,body_hash CHAR(64) NOT NULL,http_status SMALLINT UNSIGNED NOT NULL,response_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,operation,key_value));
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(100),details_json JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE SET NULL);
